import torch.nn as nn
import torch.nn.functional as F

class SwiGLU(nn.Module):
    def __init__(self, d_model, dim_feedforward):
        super().__init__()
        self.w1 = nn.Linear(d_model, dim_feedforward)
        self.w2 = nn.Linear(d_model, dim_feedforward)
        self.w3 = nn.Linear(dim_feedforward, d_model)

    def forward(self, x):
        return self.w3(F.silu(self.w1(x)) * self.w2(x))

formula:Adaptive Top-K Dynamic Allocation
math: K_{\text{adaptive}} = K_{\text{min}} + \lfloor H(x) \cdot (K_{\text{max}} - K_{\text{min}}) \rfloor
desc: Scales expert capacity dynamically based on normalized Shannon routing entropy.
var: K_{\text{min}} = Base floor of active experts (e.g. 4)
var: K_{\text{max}} = Ceiling of active experts (e.g. 64)
var: H(x) = Normalized Shannon entropy: -sum(p * ln(p + 1e-9)) / ln(K_{\text{max}})
